def first_of_episode(key, batches, state):
    # Step 4: called once per sensor and rule that has new breaches in a micro-batch.
    # Yield the breaches that raise an event, and keep the newest breach time in the state.
    device_id, rule_id = key
    yield pd.DataFrame([], columns=["device_id", "rule_id", "reading_id", "event_time", "value", "severity"])


def episodes(stream, devices, device_locations):
    # Step 4: the alert stream: breaches without copies, then first_of_episode per sensor and rule.
    return breaches(stream, devices, device_locations)


def anomaly_events(sensor_readings, devices, device_locations):
    # Step 4: run episodes(...) on the stream into a memory table and return it.
    return breaches(sensor_readings, devices, device_locations)
